@namespace sv_7407a3f7b87047f880b4f33b8f3fffd9.Components.Pages.JobApplication

<nav class="d-flex justify-content-between align-items-center mb-4 p-3 bg-light rounded">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var isActive = stepIndex == CurrentStep;
        var isCompleted = CompletedSteps.Contains(stepIndex);
        var isFuture = !isActive && !isCompleted;

        <div class="d-flex align-items-center">
            <button class="btn btn-sm @GetStepClass(isActive, isCompleted, isFuture) rounded-circle me-2"
                    style="width:32px;height:32px;"
                    disabled="@isFuture"
                    @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                @if (isCompleted)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </button>
            <span class="@(isActive ? "fw-bold" : isFuture ? "text-muted" : "")">
                @StepNames[stepIndex]
            </span>
        </div>

        @if (stepIndex < StepNames.Count - 1)
        {
            <div class="flex-grow-0 mx-2 text-muted">→</div>
        }
    }
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static string GetStepClass(bool isActive, bool isCompleted, bool isFuture) =>
        isActive ? "btn-primary" : isCompleted ? "btn-success" : "btn-secondary opacity-50";
}

@namespace sv_7407a3f7b87047f880b4f33b8f3fffd9.Components.Pages.JobApplication

<div class="card mb-3">
    <div class="card-body">
        <div class="d-flex justify-content-between align-items-center mb-3">
            <h5 class="card-title mb-0">Position @EntryNumber</h5>
            @if (CanRemove)
            {
                <button class="btn btn-outline-danger btn-sm" @onclick="OnRemove">Remove</button>
            }
        </div>

        <div class="row g-3">
            <div class="col-md-6">
                <label class="form-label">Company Name *</label>
                <input class="form-control" value="@Entry.Company"
                       @onchange="e => Update(Entry with { Company = (string?)e.Value ?? string.Empty })" />
            </div>
            <div class="col-md-6">
                <label class="form-label">Job Title *</label>
                <input class="form-control" value="@Entry.Title"
                       @onchange="e => Update(Entry with { Title = (string?)e.Value ?? string.Empty })" />
            </div>
            <div class="col-md-4">
                <label class="form-label">Start Date *</label>
                <input type="date" class="form-control" value="@Entry.StartDate.ToString("yyyy-MM-dd")"
                       @onchange="e => Update(Entry with { StartDate = DateTime.Parse((string?)e.Value ?? string.Empty) })" />
            </div>
            <div class="col-md-4">
                <div class="form-check mt-4">
                    <input class="form-check-input" type="checkbox" checked="@IsCurrent"
                           @onchange="e => ToggleCurrent((bool)(e.Value ?? false))" />
                    <label class="form-check-label">Currently working here</label>
                </div>
            </div>
            @if (!IsCurrent)
            {
                <div class="col-md-4">
                    <label class="form-label">End Date</label>
                    <input type="date" class="form-control"
                           value="@(Entry.EndDate?.ToString("yyyy-MM-dd") ?? string.Empty)"
                           @onchange="e => Update(Entry with { EndDate = DateTime.TryParse((string?)e.Value, out var d) ? d : null })" />
                </div>
            }
            <div class="col-12">
                <label class="form-label">Description</label>
                <textarea class="form-control" rows="3" value="@Entry.Description"
                          @onchange="e => Update(Entry with { Description = (string?)e.Value ?? string.Empty })"></textarea>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired] public Models.WorkEntry Entry { get; set; } = default!;
    [Parameter] public int EntryNumber { get; set; }
    [Parameter] public bool CanRemove { get; set; }
    [Parameter] public EventCallback<Models.WorkEntry> OnChanged { get; set; }
    [Parameter] public EventCallback OnRemove { get; set; }

    private bool IsCurrent => Entry.EndDate is null;

    private void Update(Models.WorkEntry updated) => OnChanged.InvokeAsync(updated);

    private void ToggleCurrent(bool isCurrent)
    {
        var updated = isCurrent
            ? Entry with { EndDate = null }
            : Entry with { EndDate = DateTime.Today };
        OnChanged.InvokeAsync(updated);
    }
}

