<nav class="d-flex justify-content-between align-items-center mb-4 p-3 bg-light rounded">
    @for (int i = 0; i < StepNames.Count; i++)
    {
        var stepIndex = i;
        var isActive = stepIndex == CurrentStep;
        var isCompleted = CompletedSteps.Contains(stepIndex);
        var isFuture = !isActive && !isCompleted;

        <div class="d-flex align-items-center">
            <button class="btn btn-sm @GetStepClass(isActive, isCompleted, isFuture) rounded-circle me-2"
                    style="width:32px;height:32px;"
                    disabled="@isFuture"
                    @onclick="() => OnStepClicked.InvokeAsync(stepIndex)">
                @if (isCompleted)
                {
                    <span>✓</span>
                }
                else
                {
                    <span>@(stepIndex + 1)</span>
                }
            </button>
            <span class="@(isActive ? "fw-bold" : isFuture ? "text-muted" : "")">
                @StepNames[stepIndex]
            </span>
        </div>

        @if (stepIndex < StepNames.Count - 1)
        {
            <div class="flex-grow-0 mx-2 text-muted">→</div>
        }
    }
</nav>

@code {
    [Parameter, EditorRequired] public int CurrentStep { get; set; }
    [Parameter, EditorRequired] public HashSet<int> CompletedSteps { get; set; } = new();
    [Parameter, EditorRequired] public List<string> StepNames { get; set; } = new();
    [Parameter] public EventCallback<int> OnStepClicked { get; set; }

    private static string GetStepClass(bool isActive, bool isCompleted, bool isFuture) =>
        isActive ? "btn-primary" : isCompleted ? "btn-success" : "btn-secondary opacity-50";
}
