<h4>Personal Information</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

<div class="row g-3 mb-4">
    <div class="col-md-6">
        <label class="form-label">Full Name *</label>
        <input class="form-control" value="@Model.FullName"
               @onchange="e => Update(Model with { FullName = (string?)e.Value ?? string.Empty })" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Email *</label>
        <input type="email" class="form-control" value="@Model.Email"
               @onchange="e => Update(Model with { Email = (string?)e.Value ?? string.Empty })" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Phone *</label>
        <input type="tel" class="form-control" value="@Model.Phone"
               @onchange="e => Update(Model with { Phone = (string?)e.Value ?? string.Empty })" />
    </div>
    <div class="col-md-6">
        <label class="form-label">Address *</label>
        <input class="form-control" value="@Model.Address"
               @onchange="e => Update(Model with { Address = (string?)e.Value ?? string.Empty })" />
    </div>
</div>

<div class="d-flex justify-content-end">
    <button class="btn btn-primary" @onclick="HandleNext" disabled="@IsValidating">
        @if (IsValidating)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Next
    </button>
</div>

@code {
    [Parameter, EditorRequired] public Models.PersonalInfo Model { get; set; } = default!;
    [Parameter] public EventCallback<Models.PersonalInfo> OnChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter, EditorRequired] public Models.IApplicationService ApplicationService { get; set; } = default!;

    private string? ErrorMessage;
    private bool IsValidating;

    private void Update(Models.PersonalInfo updated) => OnChanged.InvokeAsync(updated);

    private async Task HandleNext()
    {
        ErrorMessage = null;

        if (string.IsNullOrWhiteSpace(Model.FullName) ||
            string.IsNullOrWhiteSpace(Model.Email) ||
            string.IsNullOrWhiteSpace(Model.Phone) ||
            string.IsNullOrWhiteSpace(Model.Address))
        {
            ErrorMessage = "All fields are required.";
            return;
        }

        IsValidating = true;
        var emailValid = await ApplicationService.ValidateEmailAsync(Model.Email);
        IsValidating = false;

        if (!emailValid)
        {
            ErrorMessage = "Please enter a valid email address.";
            return;
        }

        await OnNext.InvokeAsync();
    }
}

