@namespace sv_7407a3f7b87047f880b4f33b8f3fffd9.Components.Pages.JobApplication

<h4>Work History</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < Entries.Count; i++)
{
    var index = i;
    <WorkEntryForm Entry="@Entries[index]"
                   EntryNumber="@(index + 1)"
                   CanRemove="@(Entries.Count > 1)"
                   OnChanged="e => UpdateEntry(index, e)"
                   OnRemove="() => RemoveEntry(index)" />
}

<button class="btn btn-outline-primary mb-4" @onclick="AddEntry">
    + Add Another Position
</button>

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public List<Models.WorkEntry> Entries { get; set; } = new();
    [Parameter] public EventCallback<List<Models.WorkEntry>> OnChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void UpdateEntry(int index, Models.WorkEntry updated)
    {
        var list = new List<Models.WorkEntry>(Entries);
        list[index] = updated;
        OnChanged.InvokeAsync(list);
    }

    private void RemoveEntry(int index)
    {
        var list = new List<Models.WorkEntry>(Entries);
        list.RemoveAt(index);
        OnChanged.InvokeAsync(list);
    }

    private void AddEntry()
    {
        var list = new List<Models.WorkEntry>(Entries)
        {
            new("", "", DateTime.Today, null, "")
        };
        OnChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var entry in Entries)
        {
            if (string.IsNullOrWhiteSpace(entry.Company) || string.IsNullOrWhiteSpace(entry.Title))
            {
                ErrorMessage = "Company name and job title are required for all entries.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

