@namespace sv_7407a3f7b87047f880b4f33b8f3fffd9.Components.Pages.JobApplication

<h4>References</h4>

@if (!string.IsNullOrEmpty(ErrorMessage))
{
    <div class="alert alert-danger">@ErrorMessage</div>
}

@for (int i = 0; i < References.Count; i++)
{
    var index = i;
    <ReferenceForm Reference="@References[index]"
                   ReferenceNumber="@(index + 1)"
                   CanRemove="@(References.Count > 2)"
                   OnChanged="e => UpdateReference(index, e)"
                   OnRemove="() => RemoveReference(index)" />
}

@if (References.Count < 3)
{
    <button class="btn btn-outline-primary mb-4" @onclick="AddReference">
        + Add Reference
    </button>
}

<div class="d-flex justify-content-between">
    <button class="btn btn-secondary" @onclick="OnBack">Back</button>
    <button class="btn btn-primary" @onclick="HandleNext">Next</button>
</div>

@code {
    [Parameter, EditorRequired] public List<Models.Reference> References { get; set; } = new();
    [Parameter] public EventCallback<List<Models.Reference>> OnChanged { get; set; }
    [Parameter] public EventCallback OnNext { get; set; }
    [Parameter] public EventCallback OnBack { get; set; }

    private string? ErrorMessage;

    private void UpdateReference(int index, Models.Reference updated)
    {
        var list = new List<Models.Reference>(References);
        list[index] = updated;
        OnChanged.InvokeAsync(list);
    }

    private void RemoveReference(int index)
    {
        var list = new List<Models.Reference>(References);
        list.RemoveAt(index);
        OnChanged.InvokeAsync(list);
    }

    private void AddReference()
    {
        if (References.Count >= 3) return;
        var list = new List<Models.Reference>(References)
        {
            new("", "", "", "")
        };
        OnChanged.InvokeAsync(list);
    }

    private async Task HandleNext()
    {
        ErrorMessage = null;

        foreach (var r in References)
        {
            if (string.IsNullOrWhiteSpace(r.Name) ||
                string.IsNullOrWhiteSpace(r.Relationship) ||
                string.IsNullOrWhiteSpace(r.Email))
            {
                ErrorMessage = "Name, relationship, and email are required for all references.";
                return;
            }
        }

        await OnNext.InvokeAsync();
    }
}

