@page "/apply"
@using sv_7407a3f7b87047f880b4f33b8f3fffd9.Components.Pages.JobApplication
@using sv_7407a3f7b87047f880b4f33b8f3fffd9.Models
@inject IApplicationService AppService
@rendermode InteractiveServer

<PageTitle>Job Application</PageTitle>

<div class="container py-4" style="max-width: 800px;">
    <h2 class="mb-4">Job Application</h2>

    <StepIndicator CurrentStep="@_currentStep"
                   CompletedSteps="@_completedSteps"
                   StepNames="@_stepNames"
                   OnStepClicked="GoToStep" />

    @switch (_currentStep)
    {
        case 0:
            <PersonalInfoStep Model="@_personal"
                              OnChanged="p => _personal = p"
                              OnNext="NextStep"
                              ApplicationService="@AppService" />
            break;

        case 1:
            <WorkHistoryStep Entries="@_workEntries"
                             OnChanged="e => _workEntries = e"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;

        case 2:
            <ReferencesStep References="@_references"
                            OnChanged="r => _references = r"
                            OnNext="NextStep"
                            OnBack="PreviousStep" />
            break;

        case 3:
            <CoverLetterStep CoverLetter="@_coverLetter"
                             OnChanged="c => _coverLetter = c"
                             OnNext="NextStep"
                             OnBack="PreviousStep" />
            break;

        case 4:
            <ReviewStep @ref="_reviewStep"
                        Personal="@_personal"
                        WorkEntries="@_workEntries"
                        References="@_references"
                        CoverLetter="@_coverLetter"
                        OnEditSection="GoToStep"
                        OnBack="PreviousStep"
                        OnSubmit="SubmitApplication" />
            break;
    }
</div>

@code {
    private int _currentStep;
    private readonly HashSet<int> _completedSteps = new();
    private ReviewStep? _reviewStep;

    private static readonly List<string> _stepNames = new()
    {
        "Personal Info", "Work History", "References", "Cover Letter", "Review & Submit"
    };

    private PersonalInfo _personal = new("", "", "", "");
    private List<WorkEntry> _workEntries = new() { new("", "", DateTime.Today, null, "") };
    private List<Reference> _references = new() { new("", "", "", ""), new("", "", "", "") };
    private string _coverLetter = string.Empty;

    private void GoToStep(int step)
    {
        if (_completedSteps.Contains(step) || step == _currentStep)
        {
            _currentStep = step;
        }
    }

    private void NextStep()
    {
        _completedSteps.Add(_currentStep);
        _currentStep++;
    }

    private void PreviousStep()
    {
        if (_currentStep > 0) _currentStep--;
    }

    private async Task SubmitApplication()
    {
        var application = new JobApplication(
            _personal,
            new WorkHistory(_workEntries),
            _references,
            _coverLetter);

        var id = await AppService.SubmitApplicationAsync(application);
        _completedSteps.Add(_currentStep);
        _reviewStep?.ShowConfirmation(id);
    }
}

